package glitch

import data.glitch_lib

# Credential-related field patterns (substring matching for compound names)
credential_patterns := [
    "password", "pwd", "pass", "passwd",
    "secret", "secret_key", "auth_token",
    "credentials", "creds",
    "access_key", "private_key",
    "admin_password", "root_password",
    "database_password", "db_password",
    "activationkey"
]

# Weak default passwords
weak_passwords := {
    "password", "admin", "123456", "changeme",
    "root", "toor", "guest", "default",
    "password123", "admin123", "12345678"
}

# Check if value is empty password (empty string, null, or whitespace only)
is_empty_password(value) {
    value.ir_type == "String"
    regex.match("^\\s*$", value.value)
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
}

# Check if value is a weak hardcoded password
is_weak_password(value) {
    value.ir_type == "String"
    lower(value.value) == weak_passwords[_]
}

# Check if name contains credential pattern as substring (case-insensitive)
is_credential_field(name) {
    pattern := credential_patterns[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [pattern]), name)
}

# Check attribute recursively for credential fields with empty passwords
check_credential_in_value(value) = results {
    results := {{"key": key, "val": val} |
        value.ir_type == "Hash"
        [key, val] := walk_hash(value)
        is_credential_field(key)
        is_empty_password(val)
    } | {{key: "", val: value} |
        is_empty_password(value)
    }
}

# Walk through Hash to find all key-value pairs at any nesting level
walk_hash(h) = [[key_str, val]] {
    h.ir_type == "Hash"
    some k
    val := h.value[k]
    key_str := get_string_value(k)
} else = [[key_str, val]] {
    h.ir_type == "Hash"
    some k
    nested := h.value[k]
    nested.ir_type == "Hash"
    [key_str, val] := walk_hash(nested)
}

# Extract string value from String or use string representation
get_string_value(v) = v.value {
    v.ir_type == "String"
} else = "" {
    true
}

# Check for empty password in attributes
Glitch_Analysis[r] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    is_credential_field(attr.name)
    is_empty_password(attr.value)

    r := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration - Credential fields should not be set to empty or null values. (CWE-258)"
    }
}

# Check for weak hardcoded passwords in attributes
Glitch_Analysis[r] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

