    attr := attrs[_]

    is_credential_field(attr.name)
    is_weak_password(attr.value)

    r := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Weak hardcoded password - Avoid using weak or default passwords in configuration. (CWE-521, CWE-258)"
    }
}

